/* From Uiverse.io by Wlidha09  - Tags: button, hover, modern, animated */
.__UIV_SCOPE__ .center {
  width: 150px;
  height: 50px;
  position: relative;
}

.__UIV_SCOPE__ .btn {
  width: 100%;
  height: 100%;
  cursor: pointer;
  background: transparent;
  border: 1px solid #91c9ff;
  outline: none;
  transition: 1s ease-in-out;
}

.__UIV_SCOPE__ .svg {
  position: absolute;
  left: 0;
  top: 0;
  fill: none;
  stroke: #fff;
  stroke-dasharray: 150 480;
  stroke-dashoffset: 150;
  transition: 1s ease-in-out;
}

.__UIV_SCOPE__ .btn:hover {
  transition: 1s ease-in-out;
  background: #4f95da;
}

.__UIV_SCOPE__ .btn:hover .svg {
  stroke-dashoffset: -480;
}

.__UIV_SCOPE__ .btn span {
  color: white;
  font-size: 17px;
  font-weight: 100;
}
